describe('Loading Skeleton Display', () => {
  beforeEach(() => {
    cy.visit('/'); // Adjust the URL to your application's entry point
  });

  it('should display loading skeleton while fetching data', () => {
    cy.intercept('GET', '/api/data', { delay: 2000, fixture: 'data.json' }).as('fetchData');
    cy.get('.data-container').should('not.exist'); // Ensure data is not displayed initially
    cy.wait('@fetchData');
    cy.get('.loading-skeleton').should('be.visible'); // Check if loading skeleton is visible
    cy.wait('@fetchData').then(() => {
      cy.get('.loading-skeleton').should('not.exist'); // Check if loading skeleton is removed
      cy.get('.data-container').should('be.visible'); // Verify that data is displayed
    });
  });

  it('should handle API failure gracefully', () => {
    cy.intercept('GET', '/api/data', { statusCode: 500 }).as('fetchDataFail');
    cy.get('.data-container').should('not.exist'); // Ensure data is not displayed initially
    cy.wait('@fetchDataFail');
    cy.get('.loading-skeleton').should('not.exist'); // Ensure loading skeleton is removed
    cy.get('.error-message').should('be.visible'); // Verify that error message is displayed
  });
});
